-- As
set language spanish
set nocount on

select top 0
cast(null as varchar(2)) collate database_default mes,
cast(null as varchar(4)) collate database_default anno
into #tmp001_periodo
create table #tmp001_cadena(
    item int identity,
    datos varchar(max) collate database_default
)
begin try
select @data = concat('select*from(values(''', replace(@data, '~', '''),('''), '''))t(a)')
insert into #tmp001_cadena exec(@data)

select @data = concat('select*from(values(''', replace(datos, '|', ''','''), '''))t(a,b)')
from #tmp001_cadena where item = 1
insert into #tmp001_periodo exec(@data)
select*into #tmp002_consulta from dbo.mpp_quincena where 1=2

select @data = (select 'insert into ', t.tabla, replace(tt.columnas, 'xxxxx11xxxxx', t.info)
from(select t.item, concat('#tmp00', t.item, '_consulta') tabla,
replace(replace(replace(replace(replace(replace(replace(replace(t.datos,
'|',''','''), '¬', '''),('''), 'p. m.', ''), 'a. m.', ''),
char(13)+char(10), ''), char(13),''),char(10),''), char(9), '') info
from #tmp001_cadena t where t.item > 1
order by t.item offset 0 rows)t cross apply dbo.udf_nroColsDatos(t.tabla)tt
order by t.item
for xml path, type).value('.','varchar(max)')
exec(@data)

delete t from dbo.mpp_quincena t
outer apply(select*from #tmp001_periodo where mes = t.txt_mesproceso and anno = t.txt_anoproceso)tt
where not tt.mes is null

insert into dbo.mpp_quincena select*from #tmp002_consulta
select 'OK'
end try
begin catch
    select concat('ERROR: ', error_message())
end catch
go
select*from dbo.mpp_quincena
